def conferir_duplicidades(apps, schema_editor):
    """Falha ANTES de criar as restrições únicas, dizendo o que corrigir à mão."""
    from django.db.models import Count

    OSP = apps.get_model("osp", "OrdemServico")
    problemas = []
    dup = (
        OSP.objects.filter(
            gerada_automaticamente=True, achado__isnull=True, inspecao__isnull=False,
            status__in=["ABERTA", "PLANEJADA", "EXECUTADA", "EM_ANALISE", "EM_EXECUCAO", "AGUARDANDO_APROVACAO"],
        )
        .values("equipamento_id", "inspecao_id").annotate(n=Count("id")).filter(n__gt=1)
    )
    problemas += [f"OSPs automáticas abertas duplicadas (equipamento={d['equipamento_id']}, inspeção={d['inspecao_id']})" for d in dup]
    dup = OSP.objects.exclude(sequencial_global=None).values("sequencial_global").annotate(n=Count("id")).filter(n__gt=1)
    problemas += [f"sequencial_global repetido: {d['sequencial_global']}" for d in dup]
    dup = (
        OSP.objects.exclude(sequencial_cliente=None)
        .values("cliente_id", "sequencial_cliente").annotate(n=Count("id")).filter(n__gt=1)
    )
    problemas += [f"sequencial_cliente repetido (cliente={d['cliente_id']}, seq={d['sequencial_cliente']})" for d in dup]
    if problemas:
        raise RuntimeError(
            "Corrija os dados antes de migrar o app osp (nenhuma linha foi alterada):\n- "
            + "\n- ".join(problemas)
        )


def preencher_legado(apps, schema_editor):
    """OSPs anteriores ao histórico ganham a linha de criação e o início do SLA."""
    OSP = apps.get_model("osp", "OrdemServico")
    Historico = apps.get_model("osp", "HistoricoOSP")
    for osp in OSP.objects.filter(sla_iniciado_em__isnull=True).iterator():
        OSP.objects.filter(pk=osp.pk).update(sla_iniciado_em=osp.criado_em, sla_origem="LEGADO")
        h = Historico.objects.create(
            osp_id=osp.pk, tipo="CRIACAO", ator_nome="Sistema (registro anterior ao histórico)",
            status_novo=osp.status,
            alteracoes={"prioridade": osp.prioridade, "grau_risco": osp.grau_risco,
                        "sla_data": str(osp.sla_data), "origem": "LEGADO"},
        )
        # auto_now_add carimbaria "agora"; a criação real foi na data da OSP.
        Historico.objects.filter(pk=h.pk).update(criado_em=osp.criado_em)


